insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('domashnie-myasnye-kotlety', 'main', false, null, 40, 380, 4, 'medium',
   '{"ru":"Домашние сочные котлеты из говядины и свинины","en":"Juicy home-style beef & pork cutlets"}'::jsonb,
   '{"ru":"Классические котлеты из смеси говядины и свинины на размоченном в молоке хлебе — румяная корочка снаружи, сочность внутри. Вкус, знакомый с детства.","en":"Classic cutlets from a beef-and-pork mix on milk-soaked bread — a golden crust outside, juicy within. The taste everyone grew up with."}'::jsonb,
   '{"ru":["Говяжий фарш — 300 г","Свиной фарш — 300 г","Лук — 120 г","Белый хлеб — 80 г","Молоко — 120 мл","Яйцо — 1 шт","Чеснок — 1 зубчик","Панировочные сухари — 60 г","Масло для жарки — 30 мл","Соль — 8 г","Чёрный перец — по вкусу"],"en":["Beef mince — 300 g","Pork mince — 300 g","Onion — 120 g","White bread — 80 g","Milk — 120 ml","Egg — 1","Garlic — 1 clove","Breadcrumbs — 60 g","Oil for frying — 30 ml","Salt — 8 g","Black pepper — to taste"]}'::jsonb,
   '{"ru":["Замочите белый хлеб в молоке на 5 минут и отожмите.","Смешайте оба фарша с мелко нарезанным луком, чесноком, яйцом и хлебом; посолите и поперчите.","Вымешайте недолго, сформуйте котлеты и обваляйте в сухарях.","Обжарьте на среднем огне по 4–5 минут с каждой стороны до румяной корочки.","Совет: не вымешивайте фарш слишком долго — котлеты останутся нежными."],"en":["Soak the white bread in milk for 5 minutes and squeeze it out.","Combine both minces with finely chopped onion, garlic, egg and bread; season with salt and pepper.","Mix briefly, shape the cutlets and coat in breadcrumbs.","Fry over medium heat 4–5 minutes per side until golden.","Tip: don''t overwork the mince — the cutlets stay tender."]}'::jsonb,
   '{"ru":["ужин","мясо","классика"],"en":["dinner","meat","classic"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
  is_pp = excluded.is_pp,
