  servings = excluded.servings,
  difficulty = excluded.difficulty,
  title = excluded.title,
  description = excluded.description,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  tags = excluded.tags;

insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('pozharskie-kotlety', 'main', false, null, 50, 420, 4, 'medium',
   '{"ru":"Пожарские котлеты с хрустящей корочкой","en":"Pozharsky chicken cutlets with a crisp crust"}'::jsonb,
   '{"ru":"Нежнейшие куриные котлеты на сливках в панировке из хлебных кубиков, с кусочком масла внутри. Хрустят снаружи и тают во рту.","en":"The tenderest cream-enriched chicken cutlets in a cubed-bread crust, with a knob of butter hidden inside. Crunchy outside, melting within."}'::jsonb,
   '{"ru":["Куриное бедро без кожи — 600 г","Белый хлеб — 100 г","Сливки 20% — 100 мл","Лук — 80 г","Сливочное масло — 80 г","Белые сухари кубиками — 100 г","Масло для жарки — 25 мл","Соль — 7 г","Чёрный перец — по вкусу"],"en":["Skinless chicken thigh — 600 g","White bread — 100 g","Cream 20% — 100 ml","Onion — 80 g","Butter — 80 g","Cubed bread crumbs — 100 g","Oil for frying — 25 ml","Salt — 7 g","Black pepper — to taste"]}'::jsonb,
   '{"ru":["Замочите хлеб в сливках; измельчите куриное бедро с луком в фарш.","Смешайте фарш с хлебом, посолите, поперчите и охладите 20 минут.","В центр каждой котлеты вложите кусочек холодного масла и залепите.","Обваляйте котлеты в хлебной крошке-кубиках.","Обжарьте до румяности и доведите в духовке 8–10 минут при 180 °C.","Совет: работайте с холодным фаршем — так масло останется внутри."],"en":["Soak the bread in cream; mince the chicken thigh with the onion.","Mix the mince with the bread, season and chill for 20 minutes.","Tuck a piece of cold butter into the centre of each cutlet and seal.","Coat in the cubed bread crumbs.","Fry until golden, then finish in the oven 8–10 minutes at 180 °C.","Tip: keep the mince cold so the butter stays inside."]}'::jsonb,
   '{"ru":["ужин","курица","праздничное"],"en":["dinner","chicken","special"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
  is_pp = excluded.is_pp,
