  difficulty = excluded.difficulty,
  title = excluded.title,
  description = excluded.description,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  tags = excluded.tags;

insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('kurinye-kotlety-s-syrom', 'main', false, null, 45, 390, 4, 'medium',
   '{"ru":"Куриные котлеты с сырной начинкой","en":"Chicken cutlets with a melting cheese centre"}'::jsonb,
   '{"ru":"Сочные куриные котлеты с сырным сердцем, которое тянется при разломе. Секрет — плотно защипнуть края, чтобы сыр остался внутри.","en":"Juicy chicken cutlets with a molten cheese heart that stretches when you break them open. The trick is sealing the edges tightly."}'::jsonb,
   '{"ru":["Куриный фарш — 600 г","Твёрдый сыр — 150 г","Лук — 100 г","Яйцо — 1 шт","Панировочные сухари — 80 г","Сметана — 50 г","Чеснок — 1 зубчик","Масло для жарки — 25 мл","Соль — 7 г","Чёрный перец — по вкусу"],"en":["Chicken mince — 600 g","Hard cheese — 150 g","Onion — 100 g","Egg — 1","Breadcrumbs — 80 g","Sour cream — 50 g","Garlic — 1 clove","Oil for frying — 25 ml","Salt — 7 g","Black pepper — to taste"]}'::jsonb,
   '{"ru":["Смешайте куриный фарш с луком, чесноком, яйцом и сметаной; посолите и поперчите.","Расплющите порцию фарша на ладони, в центр положите брусочек сыра.","Плотно защипните края, формируя котлету, и обваляйте в сухарях.","Обжарьте на среднем огне по 4–5 минут с каждой стороны.","Совет: защипывайте края плотно, чтобы сыр не вытек."],"en":["Mix the chicken mince with onion, garlic, egg and sour cream; season.","Flatten a portion in your palm and place a stick of cheese in the centre.","Seal the edges tightly into a patty and coat in breadcrumbs.","Fry over medium heat 4–5 minutes per side.","Tip: seal the edges well so the cheese stays in."]}'::jsonb,
   '{"ru":["ужин","курица","сыр"],"en":["dinner","chicken","cheese"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
  is_pp = excluded.is_pp,
