insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('kotlety-iz-indeyki-s-kabachkom', 'main', true, null, 40, 260, 5, 'easy',
   '{"ru":"Нежные котлеты из индейки с кабачком","en":"Tender turkey & zucchini cutlets"}'::jsonb,
   '{"ru":"Лёгкие котлеты из индейки с сочным кабачком и овсяными хлопьями вместо хлеба. ПП-вариант, который держит форму и остаётся нежным.","en":"Light turkey cutlets with juicy zucchini and oats instead of bread. A healthy version that holds its shape and stays tender."}'::jsonb,
   '{"ru":["Фарш из индейки — 650 г","Кабачок — 250 г","Лук — 100 г","Яйцо — 1 шт","Овсяные хлопья — 50 г","Сметана — 40 г","Укроп — 15 г","Масло для жарки — 25 мл","Соль — 7 г","Чёрный перец — по вкусу"],"en":["Turkey mince — 650 g","Zucchini — 250 g","Onion — 100 g","Egg — 1","Rolled oats — 50 g","Sour cream — 40 g","Dill — 15 g","Oil for frying — 25 ml","Salt — 7 g","Black pepper — to taste"]}'::jsonb,
   '{"ru":["Натрите кабачок и хорошо отожмите лишнюю влагу.","Смешайте фарш индейки с кабачком, луком, яйцом, хлопьями, сметаной и укропом.","Дайте фаршу постоять 10 минут, чтобы хлопья набухли.","Сформуйте котлеты и обжарьте под крышкой по 5 минут с каждой стороны.","Совет: чем лучше отжат кабачок, тем легче котлеты держат форму."],"en":["Grate the zucchini and squeeze out the excess moisture well.","Mix the turkey mince with zucchini, onion, egg, oats, sour cream and dill.","Rest for 10 minutes so the oats swell.","Shape the cutlets and fry, covered, 5 minutes per side.","Tip: the better you squeeze the zucchini, the better they hold shape."]}'::jsonb,
   '{"ru":["ПП","ужин","индейка","кабачок"],"en":["healthy","dinner","turkey","zucchini"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
