insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('rybnye-kotlety-iz-mintaya', 'main', false, null, 45, 300, 4, 'medium',
   '{"ru":"Рыбные котлеты из минтая","en":"Pollock fish cutlets"}'::jsonb,
   '{"ru":"Мягкие и ароматные котлеты из филе минтая с укропом. Хлеб на молоке и кусочек масла делают их нежными и сочными.","en":"Soft, fragrant cutlets from pollock fillet with dill. Milk-soaked bread and a little butter keep them tender and moist."}'::jsonb,
   '{"ru":["Филе минтая — 700 г","Лук — 100 г","Белый хлеб — 80 г","Молоко — 100 мл","Яйцо — 1 шт","Сливочное масло — 40 г","Панировочные сухари — 80 г","Укроп — 10 г","Масло для жарки — 30 мл","Соль — 7 г","Чёрный перец — по вкусу"],"en":["Pollock fillet — 700 g","Onion — 100 g","White bread — 80 g","Milk — 100 ml","Egg — 1","Butter — 40 g","Breadcrumbs — 80 g","Dill — 10 g","Oil for frying — 30 ml","Salt — 7 g","Black pepper — to taste"]}'::jsonb,
   '{"ru":["Измельчите филе минтая с луком в фарш.","Добавьте размоченный в молоке хлеб, яйцо, мягкое масло и укроп; посолите.","Охладите фарш 20 минут, сформуйте котлеты и обваляйте в сухарях.","Обжарьте на среднем огне по 3–4 минуты с каждой стороны.","Совет: перед формовкой охладите фарш — он не будет липнуть."],"en":["Mince the pollock fillet with the onion.","Add milk-soaked bread, egg, soft butter and dill; season.","Chill for 20 minutes, shape and coat in breadcrumbs.","Fry over medium heat 3–4 minutes per side.","Tip: chill the mixture before shaping so it doesn''t stick."]}'::jsonb,
   '{"ru":["ужин","рыба","минтай"],"en":["dinner","fish","pollock"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
  is_pp = excluded.is_pp,
