insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('pechenochnye-kotlety-s-risom', 'main', false, null, 40, 310, 4, 'easy',
   '{"ru":"Печёночные котлеты с рисом и морковью","en":"Chicken-liver cutlets with rice"}'::jsonb,
   '{"ru":"Мягкие печёночные котлеты с варёным рисом и морковью. Быстро, бюджетно и по-настоящему сытно.","en":"Soft chicken-liver patties with boiled rice and carrot. Quick, budget-friendly and genuinely filling."}'::jsonb,
   '{"ru":["Куриная печень — 500 г","Варёный рис — 180 г","Лук — 120 г","Морковь — 100 г","Яйцо — 1 шт","Мука — 60 г","Сметана — 50 г","Масло для жарки — 30 мл","Соль — 7 г","Чёрный перец — по вкусу"],"en":["Chicken liver — 500 g","Boiled rice — 180 g","Onion — 120 g","Carrot — 100 g","Egg — 1","Flour — 60 g","Sour cream — 50 g","Oil for frying — 30 ml","Salt — 7 g","Black pepper — to taste"]}'::jsonb,
   '{"ru":["Измельчите печень с луком блендером до однородности.","Смешайте с варёным рисом, тёртой морковью, яйцом, мукой и сметаной; посолите.","Выкладывайте массу ложкой на разогретую сковороду.","Обжарьте по 3–4 минуты с каждой стороны на среднем огне.","Совет: не делайте котлеты толстыми — так они прожарятся равномерно."],"en":["Blend the liver with the onion until smooth.","Mix with boiled rice, grated carrot, egg, flour and sour cream; season.","Spoon the mixture onto a hot pan.","Fry 3–4 minutes per side over medium heat.","Tip: keep them thin so they cook through evenly."]}'::jsonb,
   '{"ru":["ужин","печень","бюджетно"],"en":["dinner","liver","budget"]}'::jsonb)
