insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('kartofelnye-kotlety-s-gribami', 'main', false, null, 60, 340, 4, 'medium',
   '{"ru":"Картофельные котлеты с грибной начинкой","en":"Potato cutlets stuffed with mushrooms"}'::jsonb,
   '{"ru":"Пышные картофельные котлеты с сочной начинкой из жареных шампиньонов внутри и хрустящей панировкой снаружи.","en":"Fluffy potato cutlets with a juicy fried-mushroom filling inside and a crunchy crust outside."}'::jsonb,
   '{"ru":["Картофель — 800 г","Шампиньоны — 300 г","Лук — 120 г","Яйцо — 1 шт","Мука — 70 г","Панировочные сухари — 100 г","Сливочное масло — 20 г","Масло для жарки — 40 мл","Соль — 8 г","Чёрный перец — по вкусу"],"en":["Potatoes — 800 g","Mushrooms — 300 g","Onion — 120 g","Egg — 1","Flour — 70 g","Breadcrumbs — 100 g","Butter — 20 g","Oil for frying — 40 ml","Salt — 8 g","Black pepper — to taste"]}'::jsonb,
   '{"ru":["Отварите картофель и разомните в пюре с маслом, остудите.","Обжарьте нарезанные грибы с луком до золотистого цвета.","Из картофельной массы сформуйте лепёшку, спрячьте внутрь грибную начинку и залепите.","Обваляйте в муке и сухарях, обжарьте до румяной корочки.","Совет: картофельная масса должна полностью остыть, иначе котлеты расплывутся."],"en":["Boil the potatoes and mash with butter, then cool.","Fry the chopped mushrooms with onion until golden.","Shape a potato patty, hide the mushroom filling inside and seal.","Coat in flour and breadcrumbs, fry until golden.","Tip: the potato must be fully cold or the cutlets spread."]}'::jsonb,
   '{"ru":["ужин","картофель","грибы","вегетарианское"],"en":["dinner","potato","mushrooms","vegetarian"]}'::jsonb)
