insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('grechnevye-kotlety-s-gribami', 'main', false, null, 40, 290, 4, 'easy',
   '{"ru":"Гречневые котлеты с грибами","en":"Buckwheat & mushroom cutlets"}'::jsonb,
   '{"ru":"Постные котлеты из варёной гречки с ароматными шампиньонами. Интересная текстура — если измельчить лишь половину крупы.","en":"Lean cutlets of boiled buckwheat with fragrant mushrooms. Blend only half the grain for a more interesting texture."}'::jsonb,
   '{"ru":["Варёная гречка — 500 г","Шампиньоны — 250 г","Лук — 120 г","Яйца — 2 шт","Мука — 50 г","Сметана — 40 г","Панировочные сухари — 80 г","Масло для жарки — 30 мл","Соль — 7 г","Чёрный перец — по вкусу"],"en":["Boiled buckwheat — 500 g","Mushrooms — 250 g","Onion — 120 g","Eggs — 2","Flour — 50 g","Sour cream — 40 g","Breadcrumbs — 80 g","Oil for frying — 30 ml","Salt — 7 g","Black pepper — to taste"]}'::jsonb,
   '{"ru":["Обжарьте нарезанные грибы с луком до готовности.","Смешайте гречку с грибами, яйцами, мукой и сметаной; посолите.","Сформуйте котлеты и обваляйте в сухарях.","Обжарьте на среднем огне по 3–4 минуты с каждой стороны.","Совет: измельчите блендером только половину гречки — текстура будет интереснее."],"en":["Fry the chopped mushrooms with onion until done.","Mix buckwheat with mushrooms, eggs, flour and sour cream; season.","Shape the cutlets and coat in breadcrumbs.","Fry over medium heat 3–4 minutes per side.","Tip: blend only half the buckwheat for a better texture."]}'::jsonb,
   '{"ru":["ужин","гречка","грибы","постное"],"en":["dinner","buckwheat","mushrooms","lean"]}'::jsonb)
