insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('kapustnye-kotlety-s-syrom', 'main', false, null, 45, 270, 4, 'easy',
   '{"ru":"Капустные котлеты с тянущимся сыром","en":"Cabbage cutlets with melty cheese"}'::jsonb,
   '{"ru":"Мягкие котлеты из тушёной капусты с манкой и сыром, который тянется при разломе. Хрустящая корочка и нежная середина.","en":"Soft cutlets of braised cabbage with semolina and cheese that stretches when broken. Crisp crust, tender middle."}'::jsonb,
   '{"ru":["Белокочанная капуста — 700 г","Твёрдый сыр — 150 г","Лук — 100 г","Яйца — 2 шт","Манная крупа — 80 г","Молоко — 100 мл","Панировочные сухари — 80 г","Укроп — 10 г","Масло для жарки — 30 мл","Соль — 7 г","Чёрный перец — по вкусу"],"en":["White cabbage — 700 g","Hard cheese — 150 g","Onion — 100 g","Eggs — 2","Semolina — 80 g","Milk — 100 ml","Breadcrumbs — 80 g","Dill — 10 g","Oil for frying — 30 ml","Salt — 7 g","Black pepper — to taste"]}'::jsonb,
   '{"ru":["Нашинкуйте капусту и потушите с луком и молоком до мягкости.","Всыпьте манку, перемешайте и дайте постоять, пока масса загустеет.","Вмешайте тёртый сыр, яйца и укроп; посолите и остудите.","Сформуйте котлеты, обваляйте в сухарях и обжарьте до румяной корочки.","Совет: перед формовкой полностью остудите капустную массу."],"en":["Shred the cabbage and braise with onion and milk until soft.","Stir in the semolina and rest until the mixture thickens.","Fold in grated cheese, eggs and dill; season and cool.","Shape the cutlets, coat in breadcrumbs and fry until golden.","Tip: cool the cabbage mixture fully before shaping."]}'::jsonb,
   '{"ru":["ужин","капуста","сыр","вегетарианское"],"en":["dinner","cabbage","cheese","vegetarian"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
